  function getActiveProfile() {
    try {
      if (fs.existsSync(ACTIVE_PROFILE_PATH)) {
        const d = JSON.parse(fs.readFileSync(ACTIVE_PROFILE_PATH, 'utf8'));
        if (d && (d.profileId || d.active)) return d.profileId || d.active;
      }
    } catch {}
    try {
      if (fs.existsSync(CUSTOM_PROFILES_PATH)) {
        const d = JSON.parse(fs.readFileSync(CUSTOM_PROFILES_PATH, 'utf8'));
        if (d && d.activeId) return d.activeId;
      }
    } catch {}
    return 'local-d';
  }

  function getCustomProfiles() {
    try {
      if (fs.existsSync(CUSTOM_PROFILES_PATH)) {
        const raw = JSON.parse(fs.readFileSync(CUSTOM_PROFILES_PATH, 'utf8'));
        if (Array.isArray(raw)) return raw;
        if (raw && Array.isArray(raw.profiles)) return raw.profiles;
      }
    } catch {}
    return [];
  }

  function saveCustomProfiles(list) {
    try {
      let existing = {};
      if (fs.existsSync(CUSTOM_PROFILES_PATH)) {
        try { existing = JSON.parse(fs.readFileSync(CUSTOM_PROFILES_PATH, 'utf8')); } catch {}
      }
      if (Array.isArray(existing)) {
        existing = list;
      } else {
        existing.profiles = list;
      }
      fs.writeFileSync(CUSTOM_PROFILES_PATH, JSON.stringify(existing, null, 2));
      return true;
    } catch (e) {
      console.error('saveCustomProfiles err:', e);
      return false;
    }
  }

  function getModelConfig() {
    try {
      if (fs.existsSync(MODEL_CONFIG_PATH)) {
        return JSON.parse(fs.readFileSync(MODEL_CONFIG_PATH, 'utf8'));
      }
    } catch {}
    return {
      proxyTarget: 'openburnbar',
      model: 'gpt-5.6-luna',
      apiKey: 'local-cliproxy',
      cursorAccount: 'Primary Cursor Account'
    };
  }

  function saveModelConfig(cfg) {
    try {
      fs.writeFileSync(MODEL_CONFIG_PATH, JSON.stringify(cfg, null, 2));
      try {
        if (cfg && cfg.model) {
          require(path.join(ROOT, "model-lib.js")).setModel(cfg.model);
        }
      } catch (_) {}
      return true;
    } catch (e) {
      console.error('saveModelConfig err:', e);
      return false;
    }
  }

  function switchProfile(target) {
    try {
      const child = spawn(process.execPath, [SWITCH, "switch", target], {
        detached: true,
        stdio: "ignore",
        env: Object.assign({}, process.env, { ELECTRON_RUN_AS_NODE: "1" }),
      });
      child.unref();
      return true;
    } catch (e) {
      console.error('switchProfile err:', e);
      return false;
    }
  }

  function checkIsThinking() {
    try {
      if (fs.existsSync(THINKING_FLAG_PATH)) {
        const d = JSON.parse(fs.readFileSync(THINKING_FLAG_PATH, 'utf8'));
        if (d.thinking && Date.now() - d.ts < 45000) return true;
      }
    } catch {}
    if (document.querySelector('button[aria-label="Stop"]') || document.querySelector('[data-is-streaming="true"]')) {
      return true;
    }
    return false;
  }

